import { Suspense } from 'react'
import { getProjectDetails, getProjectTitle } from '@/lib/data'

export default function ProjectPage({
  params,
  searchParams,
}: PageProps<'/projects/[slug]'>) {
  return (
    <main>
      <h1>
        <Suspense fallback={<ProjectTitleFromLink searchParams={searchParams} />}>
          <ProjectTitle params={params} searchParams={searchParams} />
        </Suspense>
      </h1>
      <Suspense fallback={<p>Loading project details...</p>}>
        <ProjectDetails params={params} />
      </Suspense>
    </main>
  )
}

async function ProjectTitleFromLink({
  searchParams,
}: Pick<PageProps<'/projects/[slug]'>, 'searchParams'>) {
  const { title } = await searchParams
  const linkedTitle = Array.isArray(title) ? title[0] : title

  return linkedTitle || 'Loading project...'
}

async function ProjectTitle({
  params,
  searchParams,
}: Pick<PageProps<'/projects/[slug]'>, 'params' | 'searchParams'>) {
  const { slug } = await params
  const { title } = await searchParams
  const linkedTitle = Array.isArray(title) ? title[0] : title

  return getProjectTitle(slug) || linkedTitle || 'Unknown project'
}

async function ProjectDetails({
  params,
}: Pick<PageProps<'/projects/[slug]'>, 'params'>) {
  const { slug } = await params
  const details = await getProjectDetails(slug)

  return (
    <>
      <p>{details.description}</p>
      <h2>Recent activity</h2>
      <ul>
        {details.activity.map((item) => (
          <li key={item}>{item}</li>
        ))}
      </ul>
    </>
  )
}

