'use client'

import Link from 'next/link'
import { useRouter } from 'next/navigation'
import type { MouseEvent, ReactNode } from 'react'

export function ProjectLink({
  href,
  title,
  children,
}: {
  href: string
  title: string
  children: ReactNode
}) {
  const router = useRouter()

  function navigate(event: MouseEvent<HTMLAnchorElement>) {
    if (
      event.defaultPrevented ||
      event.button !== 0 ||
      event.metaKey ||
      event.altKey ||
      event.ctrlKey ||
      event.shiftKey
    ) {
      return
    }

    event.preventDefault()
    // Title is already known here. Keep it out of the URL and out of prefetch.
    window.history.pushState({ projectTitle: title }, '', href)
    router.push(href)
  }

  return (
    <Link href={href} prefetch={false} onClick={navigate}>
      {children}
    </Link>
  )
}

