'use client'

import Link from 'next/link'
import { useRouter } from 'next/navigation'
import { startTransition, type MouseEvent, type ReactNode } from 'react'
import { setPendingProjectTitle } from './pending-project-title'

export function ProjectLink({
  href,
  title,
  children,
}: {
  href: string
  title: string
  children: ReactNode
}) {
  const router = useRouter()

  function navigate(event: MouseEvent<HTMLAnchorElement>) {
    if (
      event.defaultPrevented ||
      event.button !== 0 ||
      event.metaKey ||
      event.altKey ||
      event.ctrlKey ||
      event.shiftKey
    ) {
      return
    }

    event.preventDefault()
    setPendingProjectTitle(title)
    startTransition(() => {
      router.push(href)
    })
  }

  return (
    <Link href={href} prefetch={false} onClick={navigate}>
      {children}
    </Link>
  )
}

