import { useSearchParams } from 'next/navigation'
import { Suspense, use } from 'react'
import { readProjectTitle } from './page'

export function ProjectHeading({
  params,
  searchParams,
}: Pick<PageProps<'/projects/[slug]'>, 'params' | 'searchParams'>) {
  return (
    <h1>
      <Suspense
        fallback={
          <Suspense fallback="Loading project...">
            <LinkedTitle searchParams={searchParams} />
          </Suspense>
        }
      >
        <ResolvedTitle params={params} />
      </Suspense>
    </h1>
  )
}

function LinkedTitle({
  searchParams,
}: Pick<PageProps<'/projects/[slug]'>, 'searchParams'>) {
  const clientTitle = useSearchParams().get('title')
  const { title } = use(searchParams)
  const linkedTitle = Array.isArray(title) ? title[0] : title

  return clientTitle || linkedTitle || 'Loading project...'
}

function ResolvedTitle({
  params,
}: Pick<PageProps<'/projects/[slug]'>, 'params'>) {
  const { slug } = use(params)
  return use(readProjectTitle(slug))
